from decimal import Decimal


def monthly_totals(entries):
    """Sum amounts per calendar month.

    Returns a dict mapping "YYYY-MM" to the Decimal total, with its keys in
    chronological order. All entries must share one currency, otherwise
    ValueError is raised. An empty input returns an empty dict.
    """
    if not entries:
        return {}

    # Validate all entries share the same currency
    currencies = set(entry.currency for entry in entries)
    if len(currencies) > 1:
        raise ValueError(f"Multiple currencies found: {currencies}")

    totals = {}
    for entry in entries:
        # Zero-pad the month
        key = f"{entry.day.year}-{entry.day.month:02d}"
        totals[key] = totals.get(key, Decimal('0')) + entry.amount

    # Sort by key (chronological order)
    return dict(sorted(totals.items()))


def category_breakdown(entries, month):
    """Totals per category for one month, given as "YYYY-MM".

    Returns a list of (category, total) tuples sorted by total ascending, so
    the largest expense comes first, with ties broken by category name.
    Categories whose total is exactly zero are left out. Entries from other
    months are ignored. Same single-currency rule as monthly_totals.
    """
    if not entries:
        return []

    # Validate all entries share the same currency
    currencies = set(entry.currency for entry in entries)
    if len(currencies) > 1:
        raise ValueError(f"Multiple currencies found: {currencies}")

    # Sum by category for the given month
    category_totals = {}
    for entry in entries:
        entry_month = f"{entry.day.year}-{entry.day.month:02d}"
        if entry_month == month:
            category_totals[entry.category] = category_totals.get(entry.category, Decimal('0')) + entry.amount

    # Filter out zero totals
    category_totals = {k: v for k, v in category_totals.items() if v != Decimal('0')}

    # Sort by total ascending (largest expense first for negative), ties broken by category name
    sorted_items = sorted(category_totals.items(), key=lambda x: (x[1], x[0]))

    return sorted_items
